// src/routes/admin.ts
import crypto8 from "node:crypto";
var adminRouter = new Hono3();
var closeWeekSchema = external_exports.object({
  week: external_exports.string().regex(/^\d{4}-W\d{2}$/, "Format week harus YYYY-Www (misal 2026-W47)")
});
adminRouter.post("/admin/close-week", rateLimit({ maxRequests: 5 }), async (c) => {
  const configuredAdminToken = process.env.ADMIN_TOKEN?.trim();
  if (!configuredAdminToken) {
    return c.json({ error: "Admin token belum dikonfigurasi" }, 503);
  }
  const rawHeader = c.req.header("x-admin-token") || c.req.header("Authorization");
  let headerToken = rawHeader?.trim();
  if (headerToken?.startsWith("Bearer ")) {
    headerToken = headerToken.slice(7).trim();
  }
  if (!headerToken) {
    return c.json({ error: "Unauthorized: Admin token tidak cocok" }, 401);
  }
  const a = Buffer.from(headerToken);
  const b = Buffer.from(configuredAdminToken);
  if (a.length !== b.length || !crypto8.timingSafeEqual(a, b)) {
    return c.json({ error: "Unauthorized: Admin token tidak cocok" }, 401);
  }
  const queryWeek = c.req.query("week");
  let bodyWeek;
  try {
    const body = await c.req.json();
    bodyWeek = body?.week;
  } catch {
  }
  const targetWeek = queryWeek || bodyWeek;
  const parsed = closeWeekSchema.safeParse({ week: targetWeek });
  if (!parsed.success) {
    return c.json({ error: parsed.error.issues[0]?.message ?? "Invalid week format" }, 400);
  }
  try {
    const result = await closeAndCommitWeek(parsed.data.week);
    return c.json(result);
  } catch (err) {
    const customErr = err;
    if (customErr.status === 409 || customErr.code === "ALREADY_COMMITTED") {
      return c.json({ error: customErr.message || "Minggu sudah pernah di-commit" }, 409);
    }
    console.error("[admin/close-week error]:", err);
    const isProd = process.env.NODE_ENV === "production";
    return c.json(
      {
        error: "Gagal menutup minggu",
        ...isProd ? {} : { details: err.message }
      },
      500
    );
  }
});

// src/services/reminder.ts
import crypto9 from "node:crypto";
var REMINDER_COOLDOWN_SECONDS = 300;
var ReminderCooldownError = class extends Error {
  retryAfterSeconds;
  cooldownSeconds;
  constructor(retryAfterSeconds, cooldownSeconds = REMINDER_COOLDOWN_SECONDS) {
    super(`Harap tunggu ${retryAfterSeconds} detik sebelum mengingatkan user ini kembali`);
    this.name = "ReminderCooldownError";
    this.retryAfterSeconds = retryAfterSeconds;
    this.cooldownSeconds = cooldownSeconds;
  }
};
async function notifyReminder(params) {
  console.log(
    `[reminder] Notifikasi pengingat ${params.reminderId} terkirim dari ${params.sender.name} ke ${params.target.name}`
  );
}
async function sendSleepReminder(senderId, targetId, now = /* @__PURE__ */ new Date()) {
  if (!targetId || typeof targetId !== "string" || targetId.trim().length === 0) {
    const err = new Error("targetUserId wajib diisi");
    err.statusCode = 400;
    throw err;
  }
  if (targetId === senderId) {
    const err = new Error("Tidak bisa mengirim pengingat tidur ke diri sendiri");
    err.statusCode = 400;
    throw err;
  }
  const db = getDb();
  const senderUser = db.prepare("SELECT id, name FROM users WHERE id = ?").get(senderId);
  if (!senderUser) {
    const err = new Error("Pengguna pengirim tidak ditemukan");
    err.statusCode = 401;
    throw err;
  }
  const targetUser = db.prepare("SELECT id, name, email FROM users WHERE id = ?").get(targetId);
  if (!targetUser) {
    const err = new Error("Pengguna target tidak ditemukan");
    err.statusCode = 404;
    throw err;
  }
  const lastReminder = db.prepare(
    `SELECT created_at 
       FROM sleep_reminders 
       WHERE sender_id = ? AND target_id = ? 
       ORDER BY created_at DESC 
       LIMIT 1`
  ).get(senderId, targetId);
  if (lastReminder) {
    const lastTime = new Date(lastReminder.created_at).getTime();
    const currentTime = now.getTime();
    const elapsedSeconds = (currentTime - lastTime) / 1e3;
    if (elapsedSeconds < REMINDER_COOLDOWN_SECONDS) {
      const retryAfterSeconds = Math.max(1, Math.ceil(REMINDER_COOLDOWN_SECONDS - elapsedSeconds));
      throw new ReminderCooldownError(retryAfterSeconds, REMINDER_COOLDOWN_SECONDS);
    }
  }
  const reminderId = `rem-${crypto9.randomUUID()}`;
  const createdAtStr = now.toISOString();
  db.prepare(
    `INSERT INTO sleep_reminders (id, sender_id, target_id, created_at, read_at)
     VALUES (?, ?, ?, ?, NULL)`
  ).run(reminderId, senderId, targetId, createdAtStr);
  await notifyReminder({
    reminderId,
    sender: senderUser,
    target: targetUser,
    createdAt: createdAtStr
  });
  return {
    id: reminderId,
    senderId,
    targetId,
    createdAt: createdAtStr,
    readAt: null,
    cooldownSeconds: REMINDER_COOLDOWN_SECONDS
  };
}
function getActiveCooldowns(senderId, now = /* @__PURE__ */ new Date()) {
  const db = getDb();
  const rows = db.prepare(
    `SELECT target_id, MAX(created_at) as last_sent_at
       FROM sleep_reminders
       WHERE sender_id = ?
       GROUP BY target_id`
  ).all(senderId);
  const cooldowns = {};
  const currentTime = now.getTime();
  for (const row of rows) {
    const lastTime = new Date(row.last_sent_at).getTime();
    const elapsedSeconds = (currentTime - lastTime) / 1e3;
    if (elapsedSeconds < REMINDER_COOLDOWN_SECONDS) {
      cooldowns[row.target_id] = Math.max(1, Math.ceil(REMINDER_COOLDOWN_SECONDS - elapsedSeconds));
    }
  }
  return cooldowns;
}
function getUnreadReminders(targetId) {
  const db = getDb();
  const rows = db.prepare(
    `SELECT r.id, r.sender_id as senderId, u.name as senderName, u.avatar as senderAvatar, r.created_at as createdAt
       FROM sleep_reminders r
       JOIN users u ON r.sender_id = u.id
       WHERE r.target_id = ? AND r.read_at IS NULL
       ORDER BY r.created_at ASC`
  ).all(targetId);
  return rows.map((r2) => ({
    ...r2,
    message: `${r2.senderName} mengingatkan kamu untuk tidur!`
  }));
}
function markReminderAsRead(targetId, reminderId, readAt = /* @__PURE__ */ new Date()) {
  const db = getDb();
  const result = db.prepare(
    `UPDATE sleep_reminders 
       SET read_at = ? 
       WHERE id = ? AND target_id = ? AND read_at IS NULL`
  ).run(readAt.toISOString(), reminderId, targetId);
  return result.changes > 0;
}
function markAllRemindersAsRead(targetId, readAt = /* @__PURE__ */ new Date()) {
  const db = getDb();
  const result = db.prepare(
    `UPDATE sleep_reminders 
       SET read_at = ? 
       WHERE target_id = ? AND read_at IS NULL`
  ).run(readAt.toISOString(), targetId);
  return Number(result.changes);
}

